public class Main {
    public static void main(String[] args) {
        String raw = "  aman kumar  ";
        String name = raw.trim();
        String[] parts = name.split(" ");
        System.out.println(name.length());
        System.out.println(parts.length);
        System.out.println(name.startsWith("aman"));
        System.out.println("AMAN".equalsIgnoreCase(parts[0]));
    }
}

public class Main {
    public static void main(String[] args) {
        String word = "BroCode";
        String reversed = new StringBuilder(word).reverse().toString();
        System.out.println(reversed);
        System.out.println(word.equals(reversed) ? "palindrome" : "not palindrome");
        System.out.println(word.length() == reversed.length());
    }
}

